/**
 * Landmass Studio 2.5D ocean.
 *
 * Adapted from Terrain Studio's Mei-style virtual-pipe water, but reduced
 * to the simple Landmass bed: bed elevation + water depth drive four pipe
 * fluxes, flux divergence changes depth, and depth-averaged velocity is
 * limited by shallow-water speed. Foam is not an instant colour trick: the
 * G channel of the water state is a persistent whitewater quantity that is
 * generated by depth-limited breaking/uprush/impact, advected with the
 * simulated velocity, diffused slightly, and decayed over time. A separate
 * foam surface mesh is displaced by that simulated state.
 */

import * as THREE from 'three';
import { computeOceanConnectedMask, sampleLandmassHeight } from '../core/landmass.js';

const PASS_VERTEX = /* glsl */`
out vec2 vUv;
void main() {
  vUv = uv;
  gl_Position = vec4(position.xy, 0.0, 1.0);
}
`;

const OCEAN_COMMON = /* glsl */`
uniform sampler2D uBedTex;
uniform vec4 uDomain; // gridRes, cellSize m, worldSpan m, seaLevel m
uniform vec4 uSim;    // dt, time, gravity, foamLifetime sec
uniform vec4 uWaveA; // dirX, dirZ, waveHeight m, waveLength m
uniform vec4 uWaveB; // surfStrength, waveMakerStrength, foamThreshold, oceanEnabled

float bedAt(ivec2 c) {
  ivec2 cc = clamp(c, ivec2(0), ivec2(int(uDomain.x) - 1));
  return texelFetch(uBedTex, cc, 0).r;
}

float oceanMaskAt(ivec2 c) {
  ivec2 cc = clamp(c, ivec2(0), ivec2(int(uDomain.x) - 1));
  return texelFetch(uBedTex, cc, 0).g;
}

vec2 cellWorld(ivec2 c) {
  return (vec2(c) / max(1.0, uDomain.x - 1.0) - 0.5) * uDomain.z;
}

float waveEta(vec2 worldXZ) {
  vec2 dir = normalize(uWaveA.xy + vec2(1e-5));
  float k = 6.2831853 / max(20.0, uWaveA.w);
  // Mei virtual pipes propagate at approximately sqrt(g * cellSize), not
  // at the deep-water phase speed. Forcing at the pipe model's own
  // celerity lets boundary swell actually couple into and cross the shelf.
  float omega = sqrt(max(0.2, uSim.z) * max(1.0, uDomain.y)) * k;
  float phase = dot(dir, worldXZ) * k - uSim.y * omega;
  float group = 0.55 + 0.45 * sin(dot(dir, worldXZ) * 0.006 - uSim.y * 0.11);
  return uWaveA.z * group * (0.72 * sin(phase) + 0.28 * sin(phase * 1.73 + 1.7));
}
`;

export const LANDMASS_OCEAN_INIT_FRAG = /* glsl */`
out vec4 outState;
in vec2 vUv;
${OCEAN_COMMON}
void main() {
  ivec2 c = ivec2(gl_FragCoord.xy);
  float bed = bedAt(c);
  float connected = oceanMaskAt(c);
  float restingDepth = max(0.0, uDomain.w - bed);
  // Start from an ocean that already contains the incoming swell field;
  // reset() then warms the pipes up so coasts away from the domain edge
  // do not sit motionless while the first boundary wave crosses the shelf.
  float eta = waveEta(cellWorld(c)) * smoothstep(0.5, 7.0, restingDepth);
  float depth = connected * max(0.0, uDomain.w + eta - bed);
  outState = vec4(depth, 0.0, 0.0, 0.0);
}
`;

export const LANDMASS_OCEAN_FLUX_FRAG = /* glsl */`
out vec4 outFlux;
in vec2 vUv;
uniform sampler2D uStateTex;
uniform sampler2D uFluxTex;
${OCEAN_COMMON}

vec4 stateAt(ivec2 c) {
  ivec2 cc = clamp(c, ivec2(0), ivec2(int(uDomain.x) - 1));
  return texelFetch(uStateTex, cc, 0);
}

void main() {
  ivec2 c = ivec2(gl_FragCoord.xy);
  int maxI = int(uDomain.x) - 1;
  float cell = uDomain.y;
  float dt = max(1e-4, uSim.x);
  float bedC = bedAt(c);
  vec4 stateC = stateAt(c);
  float depth = max(0.0, stateC.r);
  if (depth <= 1e-6 || uWaveB.w < 0.5) {
    outFlux = vec4(0.0);
    return;
  }

  float surfC = bedC + depth;
  float surfR = bedAt(c + ivec2(1, 0)) + max(0.0, stateAt(c + ivec2(1, 0)).r);
  float surfL = bedAt(c + ivec2(-1, 0)) + max(0.0, stateAt(c + ivec2(-1, 0)).r);
  float surfU = bedAt(c + ivec2(0, 1)) + max(0.0, stateAt(c + ivec2(0, 1)).r);
  float surfD = bedAt(c + ivec2(0, -1)) + max(0.0, stateAt(c + ivec2(0, -1)).r);
  vec4 dh = vec4(surfC - surfR, surfC - surfL, surfC - surfU, surfC - surfD);

  // The old terrain free-outfall edge becomes an ocean reservoir here:
  // outside head is the incoming ocean surface, not this cell's bed.
  float outside = uDomain.w + waveEta(cellWorld(c));
  if (c.x == maxI) dh.x = surfC - outside;
  if (c.x == 0) dh.y = surfC - outside;
  if (c.y == maxI) dh.z = surfC - outside;
  if (c.y == 0) dh.w = surfC - outside;

  float area = cell * cell;
  vec4 oldFlux = texelFetch(uFluxTex, c, 0);
  float frictionRate = 0.48 + 2.1 * exp(-depth * 1.25);
  float retain = exp(-frictionRate * dt);
  vec4 flux = max(vec4(0.0), oldFlux * retain + dh * (dt * area * uSim.z / cell));

  float sumFlux = flux.x + flux.y + flux.z + flux.w;
  if (sumFlux > 1e-7) {
    float volumeAvailable = depth * area / dt;
    float maxDh = max(max(dh.x, dh.y), max(dh.z, dh.w));
    float antiOvershoot = max(maxDh, 0.0) * area * 0.5 / dt;
    float cap = min(volumeAvailable, antiOvershoot);
    if (sumFlux > cap) flux *= cap / sumFlux;
  }
  outFlux = flux;
}
`;

export const LANDMASS_OCEAN_INTEGRATE_FRAG = /* glsl */`
out vec4 outState;
in vec2 vUv;
uniform sampler2D uStateTex;
uniform sampler2D uFluxTex;
${OCEAN_COMMON}

vec4 stateAt(ivec2 c) {
  ivec2 cc = clamp(c, ivec2(0), ivec2(int(uDomain.x) - 1));
  return texelFetch(uStateTex, cc, 0);
}

vec4 fluxAt(ivec2 c) {
  ivec2 cc = clamp(c, ivec2(0), ivec2(int(uDomain.x) - 1));
  return texelFetch(uFluxTex, cc, 0);
}

void main() {
  ivec2 c = ivec2(gl_FragCoord.xy);
  int maxI = int(uDomain.x) - 1;
  float cell = uDomain.y;
  float dt = max(1e-4, uSim.x);
  float bed = bedAt(c);
  vec4 old = stateAt(c);
  vec4 fC = fluxAt(c);

  float inL = c.x > 0 ? fluxAt(c + ivec2(-1, 0)).x : 0.0;
  float inR = c.x < maxI ? fluxAt(c + ivec2(1, 0)).y : 0.0;
  float inD = c.y > 0 ? fluxAt(c + ivec2(0, -1)).z : 0.0;
  float inU = c.y < maxI ? fluxAt(c + ivec2(0, 1)).w : 0.0;
  float totalIn = inL + inR + inD + inU;
  float totalOut = fC.x + fC.y + fC.z + fC.w;
  float dDepth = uWaveB.w > 0.5 ? dt * (totalIn - totalOut) / (cell * cell) : 0.0;
  float depth = max(0.0, old.r + dDepth);

  float qX = 0.5 * ((inL - fC.y) + (fC.x - inR)) / cell;
  float qZ = 0.5 * ((inD - fC.w) + (fC.z - inU)) / cell;
  float avgDepth = max(0.08, old.r + 0.5 * dDepth);
  float vMax = 1.35 + 2.9 * sqrt(avgDepth);
  vec2 velocity = clamp(vec2(qX, qZ) / avgDepth, vec2(-vMax), vec2(vMax));
  if (depth <= 0.001) velocity = vec2(0.0);
  float speed = length(velocity);

  // Ocean reservoir / wave maker. Only ocean-connected deep cells near the
  // domain edge are relaxed toward the incoming swell; the virtual pipes
  // then carry that water toward and up the shore themselves.
  vec2 worldXZ = cellWorld(c);
  float edgeCells = float(min(min(c.x, c.y), min(maxI - c.x, maxI - c.y)));
  float edgeDistance = edgeCells * cell;
  float restingDepth = max(0.0, uDomain.w - bed);
  float maker = oceanMaskAt(c)
    * smoothstep(5.0, 18.0, restingDepth)
    * (1.0 - smoothstep(uDomain.z * 0.035, uDomain.z * 0.16, edgeDistance));
  float targetDepth = max(0.0, uDomain.w + waveEta(worldXZ) - bed);
  float relax = 1.0 - exp(-dt * (0.7 + 4.5 * uWaveB.y));
  depth = mix(depth, targetDepth, clamp(maker * relax * uWaveB.y, 0.0, 1.0));

  // Persistent simulated whitewater. It is advected from where the water
  // came from, spread a little to neighbouring cells, then given sources
  // only where the shallow-water state says a wave is breaking, running up
  // a beach, or striking a steep shore.
  vec2 texel = vec2(1.0 / max(1.0, uDomain.x - 1.0));
  vec2 backUv = clamp(vUv - velocity * dt / max(1.0, uDomain.z), texel, vec2(1.0) - texel);
  float foamAdvected = texture(uStateTex, backUv).g;
  float foamNeighbours = 0.25 * (
    stateAt(c + ivec2(1, 0)).g + stateAt(c + ivec2(-1, 0)).g +
    stateAt(c + ivec2(0, 1)).g + stateAt(c + ivec2(0, -1)).g
  );
  float foam = mix(foamAdvected, foamNeighbours, 0.035);
  float foamDecayRate = mix(0.45, 1.0, smoothstep(0.03, 0.8, depth));
  foam *= exp(-dt * foamDecayRate / max(0.25, uSim.w));
  if (depth < 0.012) foam *= exp(-dt * 1.7);

  vec2 bedGradient = vec2(
    bedAt(c + ivec2(1, 0)) - bedAt(c + ivec2(-1, 0)),
    bedAt(c + ivec2(0, 1)) - bedAt(c + ivec2(0, -1))
  ) / (2.0 * cell);
  float bedSlope = length(bedGradient);
  vec2 uphill = bedSlope > 1e-5 ? bedGradient / bedSlope : vec2(0.0);
  float shorewardSpeed = dot(velocity, uphill);
  float surface = bed + depth;
  float eta = surface - uDomain.w;
  float froude = speed / sqrt(max(0.2, uSim.z) * max(0.08, depth));
  float shallow = 1.0 - smoothstep(2.5, 9.0, depth);
  float breaker = smoothstep(0.12, 0.42, abs(eta) / max(0.18, depth))
    * smoothstep(0.2, 0.78, froude) * shallow;
  float uprush = smoothstep(0.05, 0.8, shorewardSpeed)
    * smoothstep(0.012, 0.1, depth)
    * (1.0 - smoothstep(0.55, 2.2, depth));
  float impact = smoothstep(0.18, 0.7, bedSlope)
    * smoothstep(0.25, 1.4, shorewardSpeed)
    * (1.0 - smoothstep(1.2, 4.0, depth));
  float foamSource = clamp(breaker * 1.3 + uprush * 0.95 + impact * 0.8, 0.0, 1.6);
  foam += (1.0 - clamp(foam, 0.0, 1.0))
    * (1.0 - exp(-foamSource * max(0.0, uWaveB.x) * dt * 5.5));
  foam = clamp(foam, 0.0, 1.0);
  if (depth <= 0.0005 && foamSource <= 0.001) foam *= 0.82;

  outState = vec4(depth, foam, velocity.x, velocity.y);
}
`;

const SURFACE_VERTEX = /* glsl */`
uniform sampler2D uBedTex;
uniform sampler2D uStateTex;
uniform vec4 uDomain;
uniform float uFoamLayer;
out vec2 vUv;
out vec3 vWorldPos;
out vec3 vNormal;
out vec3 vState;

float surfaceAt(ivec2 c) {
  ivec2 cc = clamp(c, ivec2(0), ivec2(int(uDomain.x) - 1));
  vec4 bed = texelFetch(uBedTex, cc, 0);
  vec4 state = texelFetch(uStateTex, cc, 0);
  return bed.r + state.r + uFoamLayer * (0.035 + state.g * 0.26);
}

void main() {
  vUv = uv;
  ivec2 c = clamp(ivec2(uv * (uDomain.x - 1.0) + 0.5), ivec2(0), ivec2(int(uDomain.x) - 1));
  vec4 state = texelFetch(uStateTex, c, 0);
  vState = state.rgb;
  vec3 p = position;
  p.y = surfaceAt(c);
  float hL = surfaceAt(c + ivec2(-1, 0));
  float hR = surfaceAt(c + ivec2(1, 0));
  float hD = surfaceAt(c + ivec2(0, -1));
  float hU = surfaceAt(c + ivec2(0, 1));
  vNormal = normalize(vec3(hL - hR, 2.0 * uDomain.y, hD - hU));
  vec4 world = modelMatrix * vec4(p, 1.0);
  vWorldPos = world.xyz;
  gl_Position = projectionMatrix * viewMatrix * world;
}
`;

const WATER_FRAGMENT = /* glsl */`
out vec4 outColor;
in vec2 vUv;
in vec3 vWorldPos;
in vec3 vNormal;
in vec3 vState;
uniform sampler2D uStateTex;
uniform vec3 uSunDir;
uniform float uOpacity;

void main() {
  vec4 state = texture(uStateTex, vUv);
  float depth = max(state.r, vState.r);
  if (depth < 0.012) discard;
  vec3 N = normalize(vNormal);
  vec3 V = normalize(cameraPosition - vWorldPos);
  vec3 L = normalize(uSunDir);
  float absorb = 1.0 - exp(-depth * 1.65);
  vec3 shallow = vec3(0.08, 0.43, 0.52);
  vec3 deep = vec3(0.015, 0.16, 0.29);
  vec3 water = mix(shallow, deep, absorb);
  float ndv = clamp(dot(N, V), 0.0, 1.0);
  float fresnel = 0.035 + 0.62 * pow(1.0 - ndv, 4.0);
  vec3 sky = vec3(0.42, 0.57, 0.72);
  vec3 H = normalize(L + V);
  float spec = pow(max(dot(N, H), 0.0), 110.0) * 1.25;
  vec3 col = mix(water, sky, fresnel * 0.72) + vec3(spec);
  // Aeration from the simulated whitewater state; the thick visible foam
  // layer is the separate displaced foam surface above this water.
  col = mix(col, vec3(0.78, 0.91, 0.96), clamp(state.g, 0.0, 1.0) * 0.2);
  float alpha = uOpacity * smoothstep(0.012, 0.09, depth) * (0.38 + absorb * 0.62);
  outColor = vec4(col, alpha);
}
`;

const FOAM_FRAGMENT = /* glsl */`
out vec4 outColor;
in vec2 vUv;
in vec3 vWorldPos;
in vec3 vNormal;
in vec3 vState;
uniform sampler2D uStateTex;
uniform vec3 uSunDir;

void main() {
  vec4 state = texture(uStateTex, vUv);
  float foam = clamp(max(state.g, vState.g), 0.0, 1.0);
  if (foam < 0.06) discard;
  vec3 N = normalize(vNormal);
  vec3 L = normalize(uSunDir);
  float diffuse = 0.48 + 0.52 * max(dot(N, L), 0.0);
  vec3 col = mix(vec3(0.68, 0.82, 0.89), vec3(1.0), smoothstep(0.08, 0.55, foam)) * diffuse;
  float alpha = smoothstep(0.06, 0.34, foam) * 0.97;
  outColor = vec4(col, alpha);
}
`;

function makeRenderTarget(size) {
  return new THREE.WebGLRenderTarget(size, size, {
    type: THREE.HalfFloatType,
    format: THREE.RGBAFormat,
    minFilter: THREE.LinearFilter,
    magFilter: THREE.LinearFilter,
    wrapS: THREE.ClampToEdgeWrapping,
    wrapT: THREE.ClampToEdgeWrapping,
    depthBuffer: false,
    stencilBuffer: false,
  });
}

function buildSurfaceGeometry(size, span) {
  const positions = new Float32Array(size * size * 3);
  const uvs = new Float32Array(size * size * 2);
  const indices = new Uint32Array((size - 1) * (size - 1) * 6);
  let p = 0;
  let q = 0;
  for (let iz = 0; iz < size; iz++) {
    const v = iz / Math.max(1, size - 1);
    const z = (v - 0.5) * span;
    for (let ix = 0; ix < size; ix++) {
      const u = ix / Math.max(1, size - 1);
      positions[p++] = (u - 0.5) * span;
      positions[p++] = 0;
      positions[p++] = z;
      uvs[q++] = u;
      uvs[q++] = v;
    }
  }
  let r = 0;
  for (let iz = 0; iz < size - 1; iz++) {
    for (let ix = 0; ix < size - 1; ix++) {
      const a = iz * size + ix;
      const b = a + 1;
      const c = a + size;
      const d = c + 1;
      indices[r++] = a;
      indices[r++] = c;
      indices[r++] = b;
      indices[r++] = b;
      indices[r++] = c;
      indices[r++] = d;
    }
  }
  const geometry = new THREE.BufferGeometry();
  geometry.setAttribute('position', new THREE.BufferAttribute(positions, 3));
  geometry.setAttribute('uv', new THREE.BufferAttribute(uvs, 2));
  geometry.setIndex(new THREE.BufferAttribute(indices, 1));
  geometry.boundingSphere = new THREE.Sphere(new THREE.Vector3(), span);
  return geometry;
}

export class LandmassOceanSimulation {
  constructor(renderer, scene, field, params = {}) {
    this.renderer = renderer;
    this.scene = scene;
    this.field = field;
    // Water resolution is deliberately independent of the land grid. The
    // bed is resampled from the physical landmass field into this grid;
    // displaySpan keeps the rendered/simulated surface in stable scene units
    // even when field.worldSpan is tens of millions of metres.
    this.size = Math.round(THREE.MathUtils.clamp(Number(params.resolution) || field.size, 64, 1024));
    this.displaySpan = Math.max(1, Number(params.displaySpan) || 2400);
    this.cellSize = this.displaySpan / Math.max(1, this.size - 1);
    this.params = {
      seaLevel: 0,
      opacity: 0.78,
      waveHeight: 0.75,
      waveLength: 145,
      waveDirection: -35,
      surfStrength: 1,
      foamLifetime: 8.5,
      speed: 1,
      enabled: true,
      showFoam: true,
      ...params,
    };
    this.simTime = 0;
    this._accumulator = 0;
    this._stepCount = 0;
    this._stepsLastSecond = 0;
    this._stepWindowTime = 0;
    this.stepsPerSecond = 0;

    this._bedHeights = new Float32Array(this.size * this.size);
    this._bedData = new Float32Array(this.size * this.size * 4);
    this.bedTexture = new THREE.DataTexture(
      this._bedData,
      this.size,
      this.size,
      THREE.RGBAFormat,
      THREE.FloatType
    );
    this.bedTexture.minFilter = THREE.NearestFilter;
    this.bedTexture.magFilter = THREE.NearestFilter;
    this.bedTexture.wrapS = THREE.ClampToEdgeWrapping;
    this.bedTexture.wrapT = THREE.ClampToEdgeWrapping;
    this.bedTexture.generateMipmaps = false;

    this.stateTargets = [makeRenderTarget(this.size), makeRenderTarget(this.size)];
    this.fluxTargets = [makeRenderTarget(this.size), makeRenderTarget(this.size)];
    this.stateIndex = 0;
    this.fluxIndex = 0;

    this._domain = { value: new THREE.Vector4(this.size, this.cellSize, this.displaySpan, this.params.seaLevel) };
    this._sim = { value: new THREE.Vector4(0.05, 0, 9.81, this.params.foamLifetime) };
    this._waveA = { value: new THREE.Vector4(0.82, -0.57, this.params.waveHeight, this.params.waveLength) };
    this._waveB = { value: new THREE.Vector4(this.params.surfStrength, 1, 0.14, 1) };
    this._sunDir = { value: new THREE.Vector3(-0.48, 0.72, 0.28).normalize() };

    const sharedSimUniforms = () => ({
      uBedTex: { value: this.bedTexture },
      uDomain: this._domain,
      uSim: this._sim,
      uWaveA: this._waveA,
      uWaveB: this._waveB,
    });
    this.initMaterial = new THREE.ShaderMaterial({
      glslVersion: THREE.GLSL3,
      uniforms: sharedSimUniforms(),
      vertexShader: PASS_VERTEX,
      fragmentShader: LANDMASS_OCEAN_INIT_FRAG,
      depthTest: false,
      depthWrite: false,
    });
    this.fluxMaterial = new THREE.ShaderMaterial({
      glslVersion: THREE.GLSL3,
      uniforms: {
        ...sharedSimUniforms(),
        uStateTex: { value: null },
        uFluxTex: { value: null },
      },
      vertexShader: PASS_VERTEX,
      fragmentShader: LANDMASS_OCEAN_FLUX_FRAG,
      depthTest: false,
      depthWrite: false,
    });
    this.integrateMaterial = new THREE.ShaderMaterial({
      glslVersion: THREE.GLSL3,
      uniforms: {
        ...sharedSimUniforms(),
        uStateTex: { value: null },
        uFluxTex: { value: null },
      },
      vertexShader: PASS_VERTEX,
      fragmentShader: LANDMASS_OCEAN_INTEGRATE_FRAG,
      depthTest: false,
      depthWrite: false,
    });

    this.passScene = new THREE.Scene();
    this.passCamera = new THREE.OrthographicCamera(-1, 1, 1, -1, 0, 1);
    this.passQuad = new THREE.Mesh(new THREE.PlaneGeometry(2, 2), this.initMaterial);
    this.passQuad.frustumCulled = false;
    this.passScene.add(this.passQuad);

    this.surfaceGeometry = buildSurfaceGeometry(this.size, this.displaySpan);
    this.waterMaterial = new THREE.ShaderMaterial({
      glslVersion: THREE.GLSL3,
      uniforms: {
        uBedTex: { value: this.bedTexture },
        uStateTex: { value: null },
        uDomain: this._domain,
        uFoamLayer: { value: 0 },
        uSunDir: this._sunDir,
        uOpacity: { value: this.params.opacity },
      },
      vertexShader: SURFACE_VERTEX,
      fragmentShader: WATER_FRAGMENT,
      transparent: true,
      depthWrite: false,
      side: THREE.FrontSide,
    });
    this.foamMaterial = new THREE.ShaderMaterial({
      glslVersion: THREE.GLSL3,
      uniforms: {
        uBedTex: { value: this.bedTexture },
        uStateTex: { value: null },
        uDomain: this._domain,
        uFoamLayer: { value: 1 },
        uSunDir: this._sunDir,
      },
      vertexShader: SURFACE_VERTEX,
      fragmentShader: FOAM_FRAGMENT,
      transparent: true,
      depthWrite: false,
      side: THREE.DoubleSide,
      polygonOffset: true,
      polygonOffsetFactor: -2,
      polygonOffsetUnits: -2,
    });
    this.waterMesh = new THREE.Mesh(this.surfaceGeometry, this.waterMaterial);
    this.waterMesh.frustumCulled = false;
    this.waterMesh.renderOrder = 3;
    this.foamMesh = new THREE.Mesh(this.surfaceGeometry, this.foamMaterial);
    this.foamMesh.frustumCulled = false;
    this.foamMesh.renderOrder = 4;
    this.scene.add(this.waterMesh);
    this.scene.add(this.foamMesh);

    this.setField(field, true);
    this.setParams(this.params);
  }

  _renderPass(material, target) {
    this.passQuad.material = material;
    this.renderer.setRenderTarget(target);
    this.renderer.render(this.passScene, this.passCamera);
    this.renderer.setRenderTarget(null);
  }

  _clearTarget(target) {
    const oldColor = new THREE.Color();
    this.renderer.getClearColor(oldColor);
    const oldAlpha = this.renderer.getClearAlpha();
    this.renderer.setRenderTarget(target);
    this.renderer.setClearColor(0x000000, 0);
    this.renderer.clear(true, false, false);
    this.renderer.setRenderTarget(null);
    this.renderer.setClearColor(oldColor, oldAlpha);
  }

  _syncRenderTextures() {
    const tex = this.stateTargets[this.stateIndex].texture;
    this.waterMaterial.uniforms.uStateTex.value = tex;
    this.foamMaterial.uniforms.uStateTex.value = tex;
  }

  syncBed(recomputeOceanMask = true) {
    // Resample the physical landmass bed onto the independent water grid.
    // When the resolutions happen to match this is a direct copy; otherwise
    // every water cell samples the true physical heightfield coordinates.
    if (this.size === this.field.size) {
      this._bedHeights.set(this.field.heights);
    } else {
      const physicalSpan = this.field.worldSpan;
      let i = 0;
      for (let iz = 0; iz < this.size; iz++) {
        const physicalZ = (iz / Math.max(1, this.size - 1) - 0.5) * physicalSpan;
        for (let ix = 0; ix < this.size; ix++) {
          const physicalX = (ix / Math.max(1, this.size - 1) - 0.5) * physicalSpan;
          this._bedHeights[i++] = sampleLandmassHeight(this.field, physicalX, physicalZ);
        }
      }
    }

    const sampledField = {
      size: this.size,
      heights: this._bedHeights,
      worldSpan: this.field.worldSpan,
    };
    const mask = recomputeOceanMask
      ? computeOceanConnectedMask(sampledField, this.params.seaLevel)
      : this._lastOceanMask;
    this._lastOceanMask = mask && mask.length === this._bedHeights.length
      ? mask
      : computeOceanConnectedMask(sampledField, this.params.seaLevel);

    for (let i = 0; i < this._bedHeights.length; i++) {
      const o = i * 4;
      this._bedData[o] = this._bedHeights[i];
      this._bedData[o + 1] = this._lastOceanMask[i] || 0;
      this._bedData[o + 2] = 0;
      this._bedData[o + 3] = 1;
    }
    this.bedTexture.needsUpdate = true;
  }

  setField(field, reset = true) {
    this.field = field;
    this.syncBed(true);
    if (reset) this.reset();
  }

  reset(warmupSteps = null) {
    this.simTime = 0;
    this._accumulator = 0;
    this._sim.value.y = 0;
    this.stateIndex = 0;
    this.fluxIndex = 0;
    this._renderPass(this.initMaterial, this.stateTargets[0]);
    this._renderPass(this.initMaterial, this.stateTargets[1]);
    this._clearTarget(this.fluxTargets[0]);
    this._clearTarget(this.fluxTargets[1]);
    this._syncRenderTextures();
    // Warm the seeded swell up so pipe flux/velocity and the first breaking
    // foam exist before presentation. Higher resolutions use fewer warm-up
    // steps because each step touches many more cells.
    if (this.params.enabled) {
      const defaultWarmupSteps = Math.round(THREE.MathUtils.clamp(36864 / this.size, 48, 144));
      const requestedSteps = warmupSteps == null ? defaultWarmupSteps : (Math.floor(warmupSteps) || 0);
      const steps = Math.max(0, Math.min(240, requestedSteps));
      for (let i = 0; i < steps; i++) this.stepOnce(0.05);
    }
  }

  setParams(next = {}) {
    Object.assign(this.params, next);
    const angle = THREE.MathUtils.degToRad(Number(this.params.waveDirection) || 0);
    this._domain.value.set(this.size, this.cellSize, this.displaySpan, Number(this.params.seaLevel) || 0);
    this._sim.value.set(0.05, this.simTime, 9.81, Math.max(0.25, Number(this.params.foamLifetime) || 8.5));
    this._waveA.value.set(
      Math.cos(angle),
      Math.sin(angle),
      Math.max(0, Number(this.params.waveHeight) || 0),
      Math.max(20, Number(this.params.waveLength) || 145)
    );
    this._waveB.value.set(
      Math.max(0, Number(this.params.surfStrength) || 0),
      1,
      0.14,
      this.params.enabled ? 1 : 0
    );
    this.waterMaterial.uniforms.uOpacity.value = THREE.MathUtils.clamp(Number(this.params.opacity) ?? 0.78, 0.05, 1);
    this.waterMesh.visible = Boolean(this.params.enabled);
    this.foamMesh.visible = Boolean(this.params.enabled && this.params.showFoam);
  }

  setSeaLevel(seaLevel, reset = false) {
    this.setParams({ seaLevel });
    this.syncBed(true);
    if (reset) this.reset();
  }

  stepOnce(dt = 0.05) {
    if (!this.params.enabled) return;
    this.simTime += dt;
    this._sim.value.x = dt;
    this._sim.value.y = this.simTime;

    const currentState = this.stateTargets[this.stateIndex];
    const nextState = this.stateTargets[1 - this.stateIndex];
    const currentFlux = this.fluxTargets[this.fluxIndex];
    const nextFlux = this.fluxTargets[1 - this.fluxIndex];

    this.fluxMaterial.uniforms.uStateTex.value = currentState.texture;
    this.fluxMaterial.uniforms.uFluxTex.value = currentFlux.texture;
    this._renderPass(this.fluxMaterial, nextFlux);
    this.fluxIndex = 1 - this.fluxIndex;

    this.integrateMaterial.uniforms.uStateTex.value = currentState.texture;
    this.integrateMaterial.uniforms.uFluxTex.value = nextFlux.texture;
    this._renderPass(this.integrateMaterial, nextState);
    this.stateIndex = 1 - this.stateIndex;
    this._stepCount++;
    this._syncRenderTextures();
  }

  update(deltaSeconds = 0.016) {
    if (!this.params.enabled) return 0;
    const speed = Math.max(0, Number(this.params.speed) || 0);
    const dt = 0.05;
    this._accumulator += Math.min(Math.max(deltaSeconds, 0), 0.05) * 6 * speed;
    const maxSteps = this.size >= 768 ? 4 : this.size >= 512 ? 6 : 8;
    let steps = 0;
    while (this._accumulator >= dt && steps < maxSteps) {
      this.stepOnce(dt);
      this._accumulator -= dt;
      steps++;
    }
    if (steps >= maxSteps) this._accumulator = 0;
    this._stepsLastSecond += steps;
    this._stepWindowTime += Math.max(0, deltaSeconds);
    if (this._stepWindowTime >= 0.75) {
      this.stepsPerSecond = Math.round(this._stepsLastSecond / Math.max(0.001, this._stepWindowTime));
      this._stepsLastSecond = 0;
      this._stepWindowTime = 0;
    }
    return steps;
  }

  dispose() {
    this.scene.remove(this.waterMesh);
    this.scene.remove(this.foamMesh);
    this.surfaceGeometry?.dispose();
    this.waterMaterial?.dispose();
    this.foamMaterial?.dispose();
    this.initMaterial?.dispose();
    this.fluxMaterial?.dispose();
    this.integrateMaterial?.dispose();
    this.passQuad?.geometry?.dispose();
    this.bedTexture?.dispose();
    for (const target of [...this.stateTargets, ...this.fluxTargets]) target.dispose();
  }
}
